// TH14 v1.00b st02.ecl.txt MainSub00 (624-634) and its GirlD01 (413-433),
// GirlD01_at (435-475), GirlD01b (477-498) closure. Source is a mid-stage wave:
// four small enemies enter from both sides, each fires one big ball every
// interval; every ball flies up and is accelerated back down 120 frames later.
// Component aliases are TH14_* from touhou-bullets.ecl (native type 18 -> 640).

const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;

// GirlD01_at 0444: etEx(0,0,2,1,-999999,...) is the birth ANIM record. Birth
// animation is omitted by policy; its position back-off is applied at fire time
// below. 0458: etExSet(0,1,0,4,120,-999999,r,A) is ACCEL: fixed direction A,
// scalar r px/frame per frame, for 120 frames. Target @N is a post-op wait, so
// the first slot holds gravity for 120 frames and the second slot clears it.
xformdef ACCEL_RAIN(scalar: fx, dir: angle) {
    @120 set_gravity(scalar * cos(dir), scalar * sin(dir));
    set_gravity(0fx, 0fx);
}

// GirlD01_at 0435-0475: one single big ball per iteration, $B=100 iterations.
async sub girl_d01_at() {
    // 0449-0470 masked literals: E 100/0.02, N 40/0.028333,
    // H 20/0.031667, !LO (Lunatic here) 10/0.036667.
    var rank: int = global(GVAR_RANK);
    var interval: int = 100;
    var accel: fx = 0.02fx;
    if rank == RANK_NORMAL { interval = 40; accel = 0.028333fx; }
    else if rank == RANK_HARD { interval = 20; accel = 0.031667fx; }
    else if rank == RANK_LUNATIC { interval = 10; accel = 0.036667fx; }
    var b: int = 100;                        // 0445 $B = 100
    while b > 0 {
        b = b - 1;                           // 0473 $B-- tests the old value
        // 0448 %A = pi/2 + RANDRAD/6: ACCEL direction; 16384bam = 90deg.
        var a1: angle = (16384 + (rand(65536) - 32768) / 6) as angle;
        // 0459 %A = -pi/2 + RANDRAD/8: muzzle direction; 49152bam = 270deg.
        var a2: angle = (49152 + (rand(65536) - 32768) / 8) as angle;
        // 0438-0444 etNew/etAim(3)/etSprite(18,3)/etCount(1,1)/etAngle(A,0)/
        // etSpeed(1,1): one big ball, color 3, speed 1, fixed direction ring.
        // 0418/0427 ANIM keeps position -= 4*speed along the ball's own angle.
        _ = fire(TH14_BIG_BALL, 3,
                 $self_x - 4fx * cos(a2), $self_y - 4fx * sin(a2),
                 1fx, a2, ACCEL_RAIN(accel, a1), none);
        wait(interval);                      // 0462-0471
    }
}

// GirlD01 0413-0433. The caller picks the enmCreateM variant via mirror:
// the child mirror bit only reflects movement (x -> -x); bullets are not
// mirrored, so both sides share one attack task.
async sub girl_d01(mirror: int) {
    set_invuln(65535);
    var dir: angle = 4096bam;                // 0421 moveVel(0.3926991, 3.0)
    if mirror != 0 { dir = 28672bam; }       // mirror x: 180deg - 22.5deg
    move_vel(0, dir, 3fx, EASE_LINEAR);      // 0421 immediate angle + speed
    move_speed(60, 0.6fx, EASE_LINEAR);      // 0422 moveSpeedTime(60, 0, 0.6)
    set_hurtbox(16fx);                       // 0423 setHurtbox(32, 32)
    set_hitbox(12fx);                        // 0424 setHitbox(24, 24)
    wait(60);                                // 0425
    spawn girl_d01_at();                     // 0426 async attack
    loop { wait(1000); }                     // 0427-0431 idle forever
}

// GirlD01b 0477-0498: plain enmCreate (no mirror), drops straight down first.
async sub girl_d01b() {
    set_invuln(65535);
    move_vel(0, 16384bam, 3fx, EASE_LINEAR); // 0485 moveVel(1.5707964, 3.0)
    move_speed(60, 0.6fx, EASE_LINEAR);      // 0486 moveSpeedTime(60, 0, 0.6)
    wait(60);                                // 0487
    move_vel(0, 4096bam, 0.6fx, EASE_LINEAR); // 0488 moveVel(0.3926991, 0.6)
    set_hurtbox(16fx);                       // 0489 (boxes set after the wait)
    set_hitbox(12fx);                        // 0490
    spawn girl_d01_at();                     // 0491
    loop { wait(1000); }                     // 0493-0496 idle forever
}

// MainSub00 0624-0634: relative creation from the stage task (final = 0,0),
// so the source x/y are used as world coordinates. enmCreateM spawns the same
// position and only sets the child mirror bit (mirror=1 argument).
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-224fx, 64fx, 1000, 0, 0, 0, girl_d01(0)); // 0626
    wait(60);                                                   // 0627
    _ = spawn_enemy(224fx, 32fx, 800, 0, 0, 0, girl_d01(1));   // 0628 M
    wait(60);                                                   // 0629
    _ = spawn_enemy(-128fx, -32fx, 800, 0, 0, 0, girl_d01b);   // 0630
    wait(60);                                                   // 0631
    _ = spawn_enemy(224fx, 80fx, 800, 0, 0, 0, girl_d01(1));   // 0632 M
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

